const ZONE_REVEAL_STAGGER_MS = 380;

function zoneRevealStyle(index: number) {
  return {
    animation: `biume-zone-in 480ms cubic-bezier(0.16,1,0.3,1) ${
      ZONE_REVEAL_DELAY_MS + index * ZONE_REVEAL_STAGGER_MS
    }ms both`,
  };
}

