/**
 * Aperçu du schéma corporel, posé dans le panneau "Compte rendu
 * propriétaire" du mockup du hero (cf. hero.tsx) : les deux mêmes zones que
 * les notes déjà affichées ("tension chaîne thoraco-lombaire",
 * "sacro-iliaque D sensible") s'allument l'une après l'autre. Animation CSS
 * inconditionnelle (`biume-zone-in`, cf. ./landing-v5.css) — le hero est
 * déjà visible au chargement, inutile d'un déclenchement au scroll.
 */
export function HeroAnatomyPreview() {
  /*
    Empilé sous 640px : à 160px d'illustration plus libellés, la colonne de
    texte tombait à ~70px et "Thoraco-lombaire · Tension" se cassait en trois
    lignes. Au-dessus, la disposition d'origine est conservée telle quelle
    (c'est celle du mockup du hero, dessiné à échelle fixe).
  */
  return (
    <div className="mb-3 flex flex-col gap-3 rounded-[12px] border border-(--lv5-line) bg-(--lv5-canvas) p-3 sm:flex-row sm:items-center sm:gap-4">
      <div className="relative w-full shrink-0 overflow-hidden rounded-[9px] bg-(--lv5-surface) sm:w-40">
        <Image
          src="/assets/images/horse-anatomy-widget.jpg"
          alt=""
          width={900}
          height={600}
          className="block h-auto w-full"
        />
        <svg
          viewBox="0 0 500 380"
          preserveAspectRatio="xMidYMid meet"
          className="absolute inset-0 h-full w-full"
        >
          {ZONES.map((zone, index) => (
            <g key={zone.label} style={zoneRevealStyle(index)}>
              <path
                d={zone.path}
                transform={zone.transform}
                fill={ZONE_ACCENTS[index]}
                fillOpacity="0.45"
                stroke={ZONE_ACCENTS[index]}
                strokeOpacity="0.9"
                strokeWidth="5"
              />
            </g>
          ))}
        </svg>
      </div>

      <div className="flex min-w-0 flex-col gap-1.5">
        <p className="m-0 text-[0.68rem] font-semibold uppercase tracking-[.05em] text-(--lv5-ink-tertiary)">
          {HERO_ANATOMY_MOCK.label}
        </p>
        <div className="flex flex-col gap-1">
          {ZONES.map((zone, index) => (
            <div
              key={zone.label}
              style={zoneRevealStyle(index)}
              className="flex items-center gap-2 text-[0.88rem] font-medium text-(--lv5-ink-mid)"
            >
              <span
                className="size-2 shrink-0 rounded-full"
                style={{ background: ZONE_ACCENTS[index] }}
              />
              {zone.label} · {zone.note}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
